CREATE TABLE "CustomerExternalProfile" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL REFERENCES "Customer"("id") ON DELETE CASCADE, "channelType" TEXT NOT NULL, "externalUserId" TEXT, "username" TEXT, "profileUrl" TEXT, "displayName" TEXT, "avatarUrl" TEXT, "isVerified" BOOLEAN NOT NULL DEFAULT false, "verifiedAt" TIMESTAMP(3), "verificationMethod" TEXT NOT NULL, "source" TEXT NOT NULL, "lastCheckedAt" TIMESTAMP(3), "status" TEXT NOT NULL, "consentId" TEXT, "metadata" JSONB, "actorId" TEXT, "auditReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "CustomerExternalProfile_customerId_channelType_idx" ON "CustomerExternalProfile"("customerId", "channelType");
CREATE TABLE "CustomerChannelSubscription" ("id" TEXT PRIMARY KEY, "customerId" TEXT NOT NULL REFERENCES "Customer"("id") ON DELETE CASCADE, "channelType" TEXT NOT NULL, "targetType" TEXT NOT NULL, "targetExternalId" TEXT, "targetName" TEXT, "isSubscribed" BOOLEAN NOT NULL DEFAULT false, "subscribedAt" TIMESTAMP(3), "unsubscribedAt" TIMESTAMP(3), "lastCheckedAt" TIMESTAMP(3), "source" TEXT NOT NULL, "verificationStatus" TEXT NOT NULL, "consentId" TEXT, "metadata" JSONB, "actorId" TEXT, "auditReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "CustomerChannelSubscription_customerId_channelType_idx" ON "CustomerChannelSubscription"("customerId", "channelType");
CREATE TABLE "MachineSimCard" ("id" TEXT PRIMARY KEY, "machineId" TEXT NOT NULL UNIQUE REFERENCES "Machine"("id") ON DELETE CASCADE, "phoneNumber" TEXT, "carrierName" TEXT, "carrierCode" TEXT, "iccid" TEXT, "imsi" TEXT, "activatedAt" TIMESTAMP(3), "deactivatedAt" TIMESTAMP(3), "lastCheckedAt" TIMESTAMP(3), "source" TEXT NOT NULL, "verificationStatus" TEXT NOT NULL, "metadata" JSONB, "actorId" TEXT, "auditReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MachineMobilePlan" ("id" TEXT PRIMARY KEY, "machineId" TEXT NOT NULL UNIQUE REFERENCES "Machine"("id") ON DELETE CASCADE, "tariffName" TEXT, "tariffStatus" TEXT NOT NULL, "monthlyFee" DECIMAL(12,2), "currentBalance" DECIMAL(12,2), "currency" TEXT NOT NULL DEFAULT 'RUB', "trafficLimitMb" INTEGER, "trafficRemainingMb" INTEGER, "nextChargeAt" TIMESTAMP(3), "autoTopUpEnabled" BOOLEAN NOT NULL DEFAULT false, "minimumBalanceThreshold" DECIMAL(12,2), "lastCheckedAt" TIMESTAMP(3), "source" TEXT NOT NULL, "verificationStatus" TEXT NOT NULL, "metadata" JSONB, "actorId" TEXT, "auditReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MachineConnectivitySnapshot" ("id" TEXT PRIMARY KEY, "machineId" TEXT NOT NULL REFERENCES "Machine"("id") ON DELETE CASCADE, "payload" JSONB NOT NULL, "source" TEXT NOT NULL, "verificationStatus" TEXT NOT NULL, "capturedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MachineConnectivitySnapshot_machineId_capturedAt_idx" ON "MachineConnectivitySnapshot"("machineId", "capturedAt");
CREATE TABLE "MachineConnectivityEvent" ("id" TEXT PRIMARY KEY, "machineId" TEXT NOT NULL REFERENCES "Machine"("id") ON DELETE CASCADE, "eventType" TEXT NOT NULL, "payload" JSONB, "occurredAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "MachineConnectivityEvent_machineId_occurredAt_idx" ON "MachineConnectivityEvent"("machineId", "occurredAt");
